const DEFAULT_CODE = "13";
// END PINS

// request.cf -> [x, y] on the map. regionCode is the ISO 3166-2 subdivision
// ("27" for Osaka); without it, the nearest prefectural capital to the latitude
// and longitude is used. Anything else falls back to Tokyo.
export function pinFor(cf) {
  const tokyo = PINS[DEFAULT_CODE].slice(0, 2);
  if (!cf || cf.country !== "JP") return tokyo;
  const code = String(cf.regionCode || "").replace(/^JP-/i, "").padStart(2, "0");
  if (PINS[code]) return PINS[code].slice(0, 2);
  const lat = Number.parseFloat(cf.latitude);
  const lon = Number.parseFloat(cf.longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return tokyo;
  let best = tokyo;
  let bestDist = Infinity;
  for (const [x, y, plat, plon] of Object.values(PINS)) {
    const d = (plat - lat) ** 2 + (plon - lon) ** 2;
    if (d < bestDist) [best, bestDist] = [[x, y], d];
  }
  return best;
}

function noStore(response) {
  const out = new Response(response.body, response);
  out.headers.set("Cache-Control", "private, no-store");
  out.headers.delete("ETag");
  out.headers.delete("Last-Modified");
  return out;
}

export async function onRequestGet(context) {
  const page = await context.next();
  if (!page.ok || !(page.headers.get("Content-Type") || "").includes("text/html")) return page;
  let pin;
  try {
    pin = pinFor(context.request.cf);
  } catch {
    return noStore(page);
  }
  const rewritten = new HTMLRewriter()
    .on("[data-visitor-pin]", {
      element(el) {
        el.setAttribute("transform", `translate(${pin[0]} ${pin[1]})`);
      },
    })
    .transform(page);
  return noStore(rewritten);
}
